-- Idempotent foundation schema. It never drops or recreates existing tables.
CREATE TABLE IF NOT EXISTS users (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, register_number VARCHAR(50) UNIQUE,
 email VARCHAR(160) NOT NULL UNIQUE, phone VARCHAR(30), password VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL,
 department VARCHAR(100), year_level VARCHAR(20), section VARCHAR(20), hostel_status VARCHAR(30), account_status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS campus_zones (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(500), risk_level VARCHAR(20) NOT NULL DEFAULT 'LOW',
 latitude DOUBLE, longitude DOUBLE, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS security_officers (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, employee_id VARCHAR(50) NOT NULL UNIQUE, assigned_zone_id BIGINT,
 availability_status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE', shift_name VARCHAR(50), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT fk_officer_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_officer_zone FOREIGN KEY (assigned_zone_id) REFERENCES campus_zones(id)
);
CREATE TABLE IF NOT EXISTS incidents (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, incident_code VARCHAR(30) NOT NULL UNIQUE, reported_by BIGINT NOT NULL, incident_type VARCHAR(40) NOT NULL,
 description TEXT NOT NULL, zone_id BIGINT, severity VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, is_silent BOOLEAN NOT NULL DEFAULT FALSE,
 anonymous_report BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, acknowledged_at TIMESTAMP NULL, assigned_at TIMESTAMP NULL,
 responding_at TIMESTAMP NULL, arrived_at TIMESTAMP NULL, resolved_at TIMESTAMP NULL, resolution_notes TEXT,
 CONSTRAINT fk_incident_reporter FOREIGN KEY (reported_by) REFERENCES users(id), CONSTRAINT fk_incident_zone FOREIGN KEY (zone_id) REFERENCES campus_zones(id)
);
CREATE TABLE IF NOT EXISTS emergency_contacts (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, relationship_name VARCHAR(80), phone VARCHAR(30) NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_contact_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS incident_assignments (id BIGINT AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT NOT NULL, officer_id BIGINT NOT NULL, assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, accepted_at TIMESTAMP NULL, completed_at TIMESTAMP NULL, CONSTRAINT fk_assignment_incident FOREIGN KEY (incident_id) REFERENCES incidents(id), CONSTRAINT fk_assignment_officer FOREIGN KEY (officer_id) REFERENCES security_officers(id));
CREATE TABLE IF NOT EXISTS incident_updates (id BIGINT AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT NOT NULL, updated_by BIGINT, old_status VARCHAR(20), new_status VARCHAR(20), message VARCHAR(1000) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_update_incident FOREIGN KEY (incident_id) REFERENCES incidents(id), CONSTRAINT fk_update_actor FOREIGN KEY (updated_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, message VARCHAR(1000) NOT NULL, notification_type VARCHAR(40) NOT NULL, read_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notification_user FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS campus_alerts (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, message VARCHAR(1500) NOT NULL, severity VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_by BIGINT NOT NULL, expires_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_alert_creator FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS safety_checkins (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, message VARCHAR(500), created_by BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', expires_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_checkin_creator FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS safe_walks (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, start_zone_id BIGINT, destination_zone_id BIGINT, status VARCHAR(20) NOT NULL DEFAULT 'REQUESTED', requested_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP NULL, CONSTRAINT fk_walk_student FOREIGN KEY (student_id) REFERENCES users(id), CONSTRAINT fk_walk_start FOREIGN KEY (start_zone_id) REFERENCES campus_zones(id), CONSTRAINT fk_walk_destination FOREIGN KEY (destination_zone_id) REFERENCES campus_zones(id));
CREATE TABLE IF NOT EXISTS evidence (id BIGINT AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT NOT NULL, uploaded_by BIGINT NOT NULL, original_filename VARCHAR(255) NOT NULL, stored_filename VARCHAR(255) NOT NULL UNIQUE, content_type VARCHAR(100) NOT NULL, file_size BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_evidence_incident FOREIGN KEY (incident_id) REFERENCES incidents(id), CONSTRAINT fk_evidence_user FOREIGN KEY (uploaded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT, detail VARCHAR(1500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_audit_actor FOREIGN KEY (actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS drills (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, description VARCHAR(1000), status VARCHAR(20) NOT NULL DEFAULT 'PLANNED', scheduled_at TIMESTAMP NULL, created_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_drill_creator FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS drill_responses (id BIGINT AUTO_INCREMENT PRIMARY KEY, drill_id BIGINT NOT NULL, user_id BIGINT NOT NULL, response_status VARCHAR(30) NOT NULL, responded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_drill_response_drill FOREIGN KEY (drill_id) REFERENCES drills(id), CONSTRAINT fk_drill_response_user FOREIGN KEY (user_id) REFERENCES users(id), UNIQUE KEY uk_drill_user (drill_id, user_id));
CREATE TABLE IF NOT EXISTS safety_checkin_responses (id BIGINT AUTO_INCREMENT PRIMARY KEY, checkin_id BIGINT NOT NULL, user_id BIGINT NOT NULL, response_status VARCHAR(30) NOT NULL, responded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_checkin_response_checkin FOREIGN KEY (checkin_id) REFERENCES safety_checkins(id), CONSTRAINT fk_checkin_response_user FOREIGN KEY (user_id) REFERENCES users(id), UNIQUE KEY uk_checkin_user (checkin_id, user_id));

